const cutoff = new Date(Date.now() - 40 * 86400000).toISOString().substring(0, 10);
const defs = [
  { id: "DGS10", label: "10-year Treasury", unit: "percent" },
  { id: "DGS2", label: "2-year Treasury", unit: "percent" },
  { id: "T10Y2Y", label: "10y minus 2y spread", unit: "percent" },
  { id: "DFF", label: "Fed funds effective", unit: "percent" },
  { id: "MORTGAGE30US", label: "30-year fixed mortgage", unit: "percent" },
  { id: "DCOILWTICO", label: "WTI crude, Cushing", unit: "USD/bbl" },
  { id: "DCOILBRENTEU", label: "Brent crude", unit: "USD/bbl" },
  { id: "CPIAUCSL", label: "CPI, all items", unit: "index" },
  { id: "UNRATE", label: "Unemployment rate", unit: "percent" },
  { id: "T10YIE", label: "10y breakeven inflation", unit: "percent" }
];
return defs.map(function (d) {
  return { json: { url: "https://fred.stlouisfed.org/graph/fredgraph.csv?id=" + d.id + "&cosd=" + cutoff, series_id: d.id, label: d.label, unit: d.unit, cutoff: cutoff } };
});

const NL = String.fromCharCode(10);
const meta = {
  DGS10: { label: "10-year Treasury", unit: "percent" },
  DGS2: { label: "2-year Treasury", unit: "percent" },
  T10Y2Y: { label: "10y minus 2y spread", unit: "percent" },
  DFF: { label: "Fed funds effective", unit: "percent" },
  MORTGAGE30US: { label: "30-year fixed mortgage", unit: "percent" },
  DCOILWTICO: { label: "WTI crude, Cushing", unit: "USD/bbl" },
  DCOILBRENTEU: { label: "Brent crude", unit: "USD/bbl" },
  CPIAUCSL: { label: "CPI, all items", unit: "index" },
  UNRATE: { label: "Unemployment rate", unit: "percent" },
  T10YIE: { label: "10y breakeven inflation", unit: "percent" }
};
const items = $input.all();
const rows = [];
const tail = {};
const parsedSeries = [];
const skipped = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  let text = null;
  if (typeof j.data === "string") { text = j.data; } else if (typeof j.body === "string") { text = j.body; }
  if (!text) { skipped.push("item" + i + ":no-text"); continue; }
  const lines = text.split(NL);
  if (lines.length < 2) { skipped.push("item" + i + ":short"); continue; }
  const head = lines[0].split(",");
  if (head.length < 2) { skipped.push("item" + i + ":no-header"); continue; }
  const sid = head[1].trim();
  const m = meta[sid];
  if (!m) { skipped.push("item" + i + ":unknown-series"); continue; }
  const obs = [];
  for (let k = 1; k < lines.length; k++) {
    const ln = lines[k].trim();
    if (!ln) { continue; }
    const parts = ln.split(",");
    if (parts.length < 2) { continue; }
    const dd = parts[0].trim();
    const vv = parts[1].trim();
    if (vv === "" || vv === ".") { continue; }
    if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(dd)) { continue; }
    const num = Number(vv);
    if (!isFinite(num)) { continue; }
    obs.push({ d: dd, v: num });
  }
  if (!obs.length) { skipped.push(sid + ":no-obs"); continue; }
  const keep = obs.slice(-45);
  for (let k = 0; k < keep.length; k++) {
    rows.push({ series_id: sid, d: keep[k].d, value: keep[k].v, label: m.label, unit: m.unit });
  }
  tail[sid] = keep;
  parsedSeries.push(sid);
}
const cat = [];
const wti = tail["DCOILWTICO"];
if (wti && wti.length >= 6) {
  const wLast = wti[wti.length - 1];
  const wPrior = wti[wti.length - 6];
  const pct = wPrior.v === 0 ? 0 : ((wLast.v - wPrior.v) / wPrior.v) * 100;
  if (Math.abs(pct) > 4) {
    cat.push({ kind: "macro", headline: "WTI crude " + (pct > 0 ? "up" : "down") + " " + Math.abs(pct).toFixed(1) + "% in 5 trading days", detail: "WTI (FRED DCOILWTICO, Cushing) moved from " + wPrior.v + " USD/bbl on " + wPrior.d + " to " + wLast.v + " USD/bbl on " + wLast.d + ", a change of " + pct.toFixed(2) + "% over 5 trading sessions. Input-cost read-through for refiners, chemicals, airlines and freight.", url: "https://fred.stlouisfed.org/series/DCOILWTICO", source: "FRED", tickers: [], industries: ["energy", "chemicals", "airlines", "trucking"], score: Math.min(95, Math.round(50 + Math.abs(pct) * 3)) });
  }
}
const t10 = tail["DGS10"];
if (t10 && t10.length >= 6) {
  const tLast = t10[t10.length - 1];
  const tPrior = t10[t10.length - 6];
  const bp = (tLast.v - tPrior.v) * 100;
  if (Math.abs(bp) > 15) {
    cat.push({ kind: "macro", headline: "10-year Treasury " + (bp > 0 ? "up" : "down") + " " + Math.abs(bp).toFixed(0) + "bp in 5 trading days", detail: "The 10-year Treasury yield (FRED DGS10) moved from " + tPrior.v + "% on " + tPrior.d + " to " + tLast.v + "% on " + tLast.d + ", a change of " + bp.toFixed(1) + " basis points over 5 trading sessions. Discount-rate read-through for long-duration equities, housing and REITs.", url: "https://fred.stlouisfed.org/series/DGS10", source: "FRED", tickers: [], industries: ["banks", "reits", "homebuilders", "utilities"], score: Math.min(95, Math.round(45 + Math.abs(bp))) });
  }
}
return [{ json: { body: { p_token: "<<IRIS_TOKEN>>", p_kind: "macro", p_rows: rows }, catalysts: cat, rowCount: rows.length, seriesParsed: parsedSeries, seriesSkipped: skipped } }];

const src = $("Parse Macro CSV").first().json;
const cat = src.catalysts || [];
if (!cat.length) {
  return [];
}
return [{ json: { body: { p_token: "<<IRIS_TOKEN>>", p_rows: cat }, catalystCount: cat.length } }];
